#!/usr/bin/env python3
"""Generate the Lisp and Rust backend packet constants from one schema."""
from pathlib import Path
import argparse

root = Path(__file__).resolve().parent.parent
parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('--check', action='store_true')
args = parser.parse_args()
entries = [line.split() for line in (root / 'protocol/lir-schema.def').read_text().splitlines()
           if line.strip() and not line.startswith('#')]
outputs = {
    'rust/kiln-cg/src/packet_schema.rs': '// Generated by tools/gen-lir-schema.py.\n' + ''.join(
        f'pub const {name}: u32 = {value};\n' for name, value in entries),
    'lisp/lir-schema.lisp': ';;;; Generated by tools/gen-lir-schema.py.\n(in-package #:kiln.kir)\n' + ''.join(
        f'(defconstant +packet-{name.lower().replace("_", "-")}+ {value})\n' for name, value in entries),
}
for name, contents in outputs.items():
    path = root / name
    if args.check:
        if not path.exists() or path.read_text() != contents:
            raise SystemExit(f'{name} needs regeneration')
    else:
        path.write_text(contents)
